import os
import time
import argparse
import tempfile

def cleanup_temp_files(days=7, dry_run=False):
    base = tempfile.gettempdir()
    cutoff = time.time() - days * 86400
    removed = []
    for root, dirs, files in os.walk(base):
        for name in files:
            path = os.path.join(root, name)
            try:
                if os.path.getmtime(path) < cutoff:
                    if dry_run:
                        removed.append(path)
                    else:
                        os.remove(path)
                        removed.append(path)
            except OSError:
                pass
    print(f"{len(removed)} file(s) "
          f"{'would be ' if dry_run else ''}removed:"
          if removed else "No files to remove.")
    for p in removed:
        print(p)
    return removed

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Delete temp files older than N days.")
    parser.add_argument("--days", type=int, default=7, help="Age threshold in days (default: 7)")
    parser.add_argument("--dry-run", action="store_true", help="List files without deleting")
    args = parser.parse_args()
    cleanup_temp_files(days=args.days, dry_run=args.dry_run)
```

`tempfile.gettempdir()` returns the current user's temp dir (e.g. `/tmp`, `%TEMP%`). Recursion into subdirectories is included since temp dirs often nest. `mtime` is used for age; `os.remove` skips directories and ignores files already gone. Errors (permissions, race conditions) are swallowed per-file so one bad path won't abort the run.

