import os


def safe_join(base_dir: str, filename: str) -> str:
    """Resolve filename within base_dir, rejecting path traversal."""
    if not isinstance(filename, str) or not filename:
        raise ValueError("filename must be a non-empty string")

    # Resolve to absolute real paths so symlinks and .. cannot escape.
    abs_base = os.path.realpath(base_dir)
    abs_target = os.path.realpath(os.path.join(abs_base, filename))

    # Ensure the resolved path stays within base_dir.
    if abs_target != abs_base and not abs_target.startswith(abs_base + os.sep):
        raise ValueError("path escapes base directory")

    return abs_target


def is_safe_filename(filename: str) -> bool:
    """Return True if filename contains no traversal or separator components."""
    if not isinstance(filename, str) or not filename:
        return False
    parts = os.path.normpath(filename).split(os.sep)
    return ".." not in parts and "" not in parts


