import tempfile


def test_safe_join_basic():
    with tempfile.TemporaryDirectory() as tmp:
        path = safe_join(tmp, "file.txt")
        assert path == os.path.join(os.path.realpath(tmp), "file.txt")


def test_safe_join_rejects_traversal():
    with tempfile.TemporaryDirectory() as tmp:
        for bad in ["../secret", "..\\secret", "../../etc/passwd", "a/../../b"]:
            try:
                safe_join(tmp, bad)
                assert False, f"should have rejected {bad!r}"
            except ValueError:
                pass


def test_safe_join_rejects_empty():
    with tempfile.TemporaryDirectory() as tmp:
        for bad in ["", "   "]:
            try:
                safe_join(tmp, bad)
                assert False, f"should have rejected {bad!r}"
            except ValueError:
                pass


def test_safe_join_allows_subdirs():
    with tempfile.TemporaryDirectory() as tmp:
        path = safe_join(tmp, "sub/dir/file.txt")
        assert os.path.dirname(path) == os.path.join(os.path.realpath(tmp), "sub", "dir")


def test_safe_join_base_dir_allowed():
    with tempfile.TemporaryDirectory() as tmp:
        # Empty-ish relative resolves to base itself (allowed).
        path = safe_join(tmp, ".")
        assert path == os.path.realpath(tmp)


